const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Makassar'});
const key='somesea-hq-v1', initial=()=>({version:1,leads:[],entries:[],tasks:[],road:[],decisions:[],start:''});
const stages=['Baru','Dihubungi','Discovery','Qualified','Proposal','Won','Lost','Nurture'];
let state=initial(),storageError=false;
try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);if(!valid(parsed))throw Error();state=parsed}}catch{storageError=true}
function valid(x){return x&&x.version===1&&['leads','entries','tasks','road','decisions'].every(k=>Array.isArray(x[k]))&&typeof x.start==='string'&&(!x.start||/^\d{4}-\d{2}-\d{2}$/.test(x.start))&&x.leads.every(l=>l&&typeof l.id==='string'&&typeof l.name==='string'&&typeof l.problem==='string'&&typeof l.next==='string'&&typeof l.date==='string'&&stages.includes(l.stage)&&Number.isFinite(l.value)&&l.value>=0)&&x.entries.every(e=>e&&typeof e.id==='string'&&typeof e.title==='string'&&['Omzet','Kas masuk','Biaya'].includes(e.type)&&/^\d{4}-\d{2}-\d{2}$/.test(e.date)&&Number.isFinite(e.value)&&e.value>0)&&x.tasks.every(t=>Number.isInteger(t)&&t>=0&&t<3)&&x.road.every(t=>Number.isInteger(t)&&t>=0&&t<8)&&x.decisions.every(d=>d&&typeof d.id==='string'&&typeof d.title==='string'&&typeof d.source==='string'&&['USULAN','EKSPERIMEN','FINAL'].includes(d.status))}
let page='home',docIndex=0,search='',filter='',month=today().slice(0,7);
const nav=[['home','◫','Overview'],['crm','♧','CRM & penjualan'],['road','↗','Roadmap 90 hari'],['finance','◷','Keuangan'],['docs','▤','Pustaka HQ'],['decisions','◇','Keputusan'],['tools','⊞','Tools & aset']];
const road=[['01–07','Rapikan fondasi','Tinjau keputusan, pilih kapasitas dan satu penawaran. Susun 10 calon prospek relevan.'],['08–14','Tunjukkan bukti awal','Buat satu demo dengan data contoh dan mulai discovery.'],['15–21','Dengarkan kebutuhan','Upayakan lima discovery. Catat masalah, anggaran, dan keberatan.'],['22–30','Uji penawaran','Kirim proposal untuk prospek yang cocok. Evaluasi pesan dan lingkup.'],['31–45','Delivery terkontrol','Jalankan SOP pada deal pertama; ukur waktu dan biaya aktual.'],['46–60','Bangun bukti hasil','Selesaikan milestone dan minta izin studi kasus.'],['61–75','Ulangi yang bekerja','Fokus pada kanal yang membawa prospek cocok.'],['76–90','Stabilkan operasi','Evaluasi target omzet dan pilih satu tool berdasarkan hambatan nyata.']];
const finals=[['Handle @somesea__','S-02 · Koreksi langsung dari Sams.'],['Somesea berasal dari pelesetan Samsi','S-02 · Filosofi personal brand.'],['Personal branding yang dekat dan natural','S-03 · Preferensi Sams.'],['Somesea HQ sebagai pusat kerja','S-01 · Permintaan pada chat ini.'],['Jasa digital AI-assisted, stack-agnostic','S-01 · Arah bisnis yang diminta.'],['Target omzet Rp5 juta per bulan','S-01 · Target, bukan pendapatan aktual.'],['Satukan komponen operasional bisnis','S-01 · Roadmap, CRM, SOP, dashboard, dan inventaris.']];
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function save(){try{localStorage.setItem(key,JSON.stringify(state));storageError=false;toast('Perubahan tersimpan di browser ini.')}catch{storageError=true;toast('Penyimpanan browser gagal. Ekspor data sebelum menutup halaman.')}render()}
function badge(s){return `<span class="badge ${s==='USULAN'||s==='EKSPERIMEN'?'proposal':s==='BELUM TERVERIFIKASI'?'unknown':''}">${esc(s)}</span>`}
function intro(title,desc,action=''){return `<div class="intro"><div><div class="eyebrow">SOMESEA WORKSPACE</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function empty(title,desc,action=''){return `<div class="empty"><div class="symbol">◌</div><h3>${title}</h3><p>${desc}</p>${action}</div>`}
function button(text,action,style='primary'){return `<button class="${style}" data-action="${action}">${text}</button>`}
function sum(type){return state.entries.filter(e=>e.type===type&&e.date.startsWith(month)).reduce((s,e)=>s+e.value,0)}
function home(){
const revenue=sum('Omzet'),due=state.leads.filter(l=>l.date&&l.date<=today()&&!['Won','Lost'].includes(l.stage)),focus=['Tetapkan kapasitas dan tanggal mulai','Pilih satu penawaran untuk diuji','Catat prospek pertama dan tindak lanjut'];
return intro('Selamat datang, Sams.','Satu ruang untuk ide, relasi, dan bisnis yang terus tumbuh.',button('+ Tambah prospek','lead'))+
`<div class="hero-grid"><section class="target"><div class="target-head"><h2>Arah bulan ini</h2><input aria-label="Bulan laporan" class="month" type="month" id="month" value="${month}"></div><div class="target-value">${money(revenue)} <span>/ Rp5.000.000</span></div><p class="tiny">${state.entries.some(e=>e.type==='Omzet'&&e.date.startsWith(month))?'Omzet dari pekerjaan yang telah diterima.':'Belum ada omzet yang dicatat untuk bulan ini.'}</p><div class="track"><i style="width:${Math.min(100,revenue/5000000*100)}%"></i></div><div class="spread tiny"><span>${Math.round(revenue/5000000*100)}% dari target</span><span>${money(Math.max(0,5000000-revenue))} lagi</span></div></section><section class="panel"><div class="panel-head"><h2>Mulai dari yang penting</h2><span class="muted tiny">${state.tasks.length}/3</span></div>${focus.map((f,i)=>`<label class="focus"><input type="checkbox" data-task="${i}" ${state.tasks.includes(i)?'checked':''}><span>${f}</span></label>`).join('')}</section></div>
<div class="stats"><div class="stat"><span class="muted tiny">Prospek aktif</span><strong>${state.leads.filter(l=>!['Won','Lost'].includes(l.stage)).length}</strong><small>Relasi yang sedang dibangun</small></div><div class="stat"><span class="muted tiny">Follow-up jatuh tempo</span><strong>${due.length}</strong><small>Langkah kecil berikutnya</small></div><div class="stat"><span class="muted tiny">Roadmap selesai</span><strong>${state.road.length}<span class="muted"> / 8</span></strong><small>Fase menuju 90 hari</small></div></div>
<div class="lower"><section class="panel"><div class="panel-head"><h2>Pipeline penjualan</h2><a href="#crm">Buka CRM ↗</a></div>${state.leads.length?leadTable(state.leads.slice(0,4)):empty('Relasi pertama dimulai dari percakapan.','Tambahkan calon klien, pahami masalahnya, lalu tentukan langkah berikutnya.',button('Tambah prospek pertama','lead','subtle'))}</section><section class="panel"><div class="panel-head"><h2>Pelan, tapi terarah.</h2>${badge('USULAN')}</div><p>Bangun fondasi, uji penawaran, lalu ulangi proses yang memberi hasil.</p><div class="steps"><div class="step"><strong>01 / Fondasi</strong><small>Hari 1–30</small></div><div class="step"><strong>02 / Bukti</strong><small>Hari 31–60</small></div><div class="step"><strong>03 / Ritme</strong><small>Hari 61–90</small></div></div><a href="#road">Lihat roadmap lengkap ↗</a></section></div><div class="note">Fondasi brand sudah terkonfirmasi. Harga, segmen, dan proses operasional masih usulan. Aset Business OS lama belum berhasil dipulihkan.</div>`}
function leadTable(leads){return `<div class="table-wrap"><table><thead><tr><th>Prospek / kebutuhan</th><th>Tahap</th><th>Langkah berikutnya</th><th></th></tr></thead><tbody>${leads.map(l=>`<tr><td><strong>${esc(l.name)}</strong><small>${esc(l.problem)}</small></td><td>${badge(l.stage)}</td><td>${esc(l.next||'Belum ditentukan')}<small>${esc(l.date)}</small></td><td><button class="subtle" data-edit="${esc(l.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`}
function crm(){const list=state.leads.filter(l=>(!filter||l.stage===filter)&&(l.name+' '+l.problem).toLowerCase().includes(search.toLowerCase()));return intro('Relasi sebelum transaksi.','Catat kebutuhan, jaga percakapan, dan buat tindak lanjut yang jelas.',button('+ Tambah prospek','lead'))+`<div class="toolbar"><input type="search" id="search" placeholder="Cari nama atau kebutuhan…" aria-label="Cari prospek" value="${esc(search)}"><select id="filter" aria-label="Filter tahap"><option value="">Semua tahap</option>${stages.map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select><span class="muted tiny">${list.length} prospek</span></div><section class="panel">${list.length?leadTable(list):empty(state.leads.length?'Tidak ada hasil yang cocok.':'CRM siap untuk prospek pertamamu.','Data asli kamu akan muncul di sini. Tidak ada prospek contoh.')}</section><div class="note">Won berarti penawaran disetujui, bukan pembayaran diterima. Catat pembayaran terpisah di Keuangan. Panduan discovery dan proposal tersedia di Pustaka HQ.</div>`}
function roadmap(){return intro('90 hari, satu arah.','Rencana kerja yang bisa kamu sesuaikan dengan kapasitas nyata.',badge('USULAN'))+`<div class="toolbar"><label>Tanggal mulai<input id="start" type="date" value="${esc(state.start)}"></label><span class="muted">${state.road.length} dari 8 fase ditandai selesai</span></div><div class="cards">${road.map((r,i)=>`<section class="panel road-card"><div class="day">HARI<br>${r[0]}</div><div><h3>${r[1]}</h3><p>${r[2]}</p><label><span><input type="checkbox" data-road="${i}" ${state.road.includes(i)?'checked':''}> Fase selesai</span></label></div></section>`).join('')}</div><div class="note">Roadmap ini rancangan baru. Tanggal mulai belum dianggap keputusan sampai kamu mengisinya. Detail evaluasi hari 30, 60, dan 90 ada di Pustaka HQ.</div>`}
function finance(){return intro('Angka yang memberi arah.','Pisahkan omzet, uang yang diterima, dan biaya.',button('+ Catat transaksi','entry'))+`<div class="toolbar"><label>Bulan laporan<input id="month" type="month" value="${month}"></label></div><div class="stats">${['Omzet','Kas masuk','Biaya'].map(t=>`<div class="stat"><span class="muted">${t}</span><strong style="font-size:23px">${money(sum(t))}</strong><small>Berdasarkan catatan bulan terpilih</small></div>`).join('')}</div><section class="panel">${state.entries.filter(e=>e.date.startsWith(month)).length?`<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Uraian</th><th>Jenis</th><th>Nilai</th><th></th></tr></thead><tbody>${state.entries.filter(e=>e.date.startsWith(month)).map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.title)}</td><td>${esc(e.type)}</td><td>${money(e.value)}</td><td><button class="subtle" data-entry="${esc(e.id)}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada catatan bulan ini.','Catat omzet saat pekerjaan diterima. Catat kas saat uang benar-benar masuk.')}</section><div class="note">Contoh: DP masuk adalah kas, bukan tambahan omzet. Nilai pekerjaan hanya dicatat sekali sebagai omzet saat diterima. Modul ini belum menghitung piutang atau pajak otomatis; ledger lengkap ada di pustaka.</div>`}
function markdown(text){
const inline=s=>esc(s).replace(/\[([^\]]+)\]\([^)]+\)/g,'$1').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');
const lines=text.split('\n');let out='',table=false;
for(let i=1;i<lines.length;i++){const line=lines[i].trim();
if(line.startsWith('|')){if(/^\|[\s:|-]+\|$/.test(line))continue;const cells=line.split('|').slice(1,-1);if(!table){out+='<div class="table-wrap"><table>';table=true}out+='<tr>'+cells.map(c=>`<td>${inline(c.trim())}</td>`).join('')+'</tr>';continue}
if(table){out+='</table></div>';table=false}
if(!line)continue;
const heading=line.match(/^(#{2,4})\s+(.*)/);if(heading){const tag='h'+Math.min(4,heading[1].length);out+=`<${tag}>${inline(heading[2])}</${tag}>`;continue}
if(line.startsWith('>')){out+=`<blockquote>${inline(line.slice(1).trim())}</blockquote>`;continue}
if(/^[-*] /.test(line)){out+=`<p class="doc-bullet">• ${inline(line.slice(2))}</p>`;continue}
out+=`<p>${inline(line)}</p>`;
}return out+(table?'</table></div>':'')
}
function docs(){const d=window.HQ_DOCS[docIndex];return intro('Semua konteks, tetap dekat.','18 dokumen sumber. Keputusan, strategi, dan cara kerja dalam satu pustaka.')+`<div class="doc-layout"><div class="doc-list">${window.HQ_DOCS.map((d,i)=>`<button data-doc="${i}" class="${i===docIndex?'active':''}">${esc(d.title)}</button>`).join('')}</div><article class="panel article"><div class="spread"><h2>${esc(d.title)}</h2>${button('↓ Unduh dokumen','download-doc','subtle')}</div><small>${esc(d.path)} · v0.1.0</small><div class="doc-body">${markdown(d.content)}</div></article></div>`}
function decisions(){return intro('Jelas mana yang disepakati.','Keputusan final punya sumber. Ide baru tetap bisa diuji.',button('+ Catat keputusan','decision'))+`<section class="panel">${finals.map((d,i)=>`<div class="decision"><div class="spread"><span class="muted tiny">D-00${i+1}</span>${badge('FINAL')}<strong>${d[0]}</strong></div><p>${d[1]}</p></div>`).join('')}${state.decisions.map(d=>`<div class="decision"><div class="spread">${badge(d.status)}<strong>${esc(d.title)}</strong></div><p>${esc(d.source)}</p><small>Dicatat oleh Sams pada workspace ini.</small></div>`).join('')}</section><div class="note">Persetujuan umum pada percakapan lama tidak dipakai untuk mengesahkan rincian yang belum terbaca. Keputusan baru ditambahkan ke log, bukan menimpa riwayat.</div>`}
function tools(){const rows=[['Master & decision log','TERSEDIA','Dokumen sumber dan versi awal sudah tersedia.'],['CRM interaktif','TERSEDIA','Tambah, edit, cari, dan filter prospek. Data disimpan di browser.'],['Dashboard & ledger','TERSEDIA','Ringkasan omzet dan catatan transaksi dari input kamu.'],['Roadmap interaktif','TERSEDIA','Tanggal mulai dan penanda fase selesai.'],['Business OS lama','BELUM TERVERIFIKASI','Berkas asli masih diperlukan untuk rekonsiliasi.'],['Kalkulator harga & kapasitas','USULAN','Dibangun setelah tersedia catatan waktu dan biaya aktual.'],['Generator proposal','USULAN','Menunggu struktur penawaran yang sudah dipakai berulang.'],['Sinkronisasi lintas perangkat','USULAN','Versi sekarang belum memiliki database cloud. Gunakan ekspor dan impor.']];return intro('Tools mengikuti kebutuhan.','Pakai yang membantu sekarang. Bangun berikutnya dari hambatan nyata.')+`<section class="panel">${rows.map(r=>`<div class="toolrow"><div><h3>${r[0]}</h3><p>${r[2]}</p></div>${badge(r[1])}</div>`).join('')}</section><div class="note">Web ini versi baru dari fondasi HQ, bukan pemulihan aplikasi lama. Semua 18 dokumen tetap disertakan. Ekspor data berisi perubahan interaktif; dokumen sumber dapat diunduh dari pustaka.</div>`}
function render(){page=location.hash.slice(1)||'home';if(!nav.some(n=>n[0]===page))page='home';$('#nav').innerHTML=nav.map(n=>`<a href="#${n[0]}" class="${page===n[0]?'active':''}" ${page===n[0]?'aria-current="page"':''}><span class="nav-icon">${n[1]}</span>${n[2]}</a>`).join('');$('#breadcrumb').textContent='Ruang kerja / '+nav.find(n=>n[0]===page)[2];$('#app').innerHTML=({home,crm,road:roadmap,finance,docs,decisions,tools}[page])();if(storageError)$('#app').insertAdjacentHTML('afterbegin','<div role="alert" class="note">Data browser tidak dapat dibaca atau disimpan. Ekspor sebelum menutup. Data lama tidak dihapus.</div>')}
function field(name,label,value='',type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''} maxlength="500"></label>`}
function select(name,label,options,value){return `<label>${label}<select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${o}</option>`).join('')}</select></label>`}
function modal(title,fields,callback){$('#modal-title').textContent=title;$('#fields').innerHTML=fields;$('#form').onsubmit=e=>{e.preventDefault();if(!$('#form').reportValidity())return;const data=Object.fromEntries(new FormData($('#form')));if(callback(data)===false)return;$('#modal').close();save()};$('#modal').showModal()}
function lead(id){const l=state.leads.find(l=>l.id===id)||{};modal(l.id?'Edit prospek':'Prospek baru',field('name','Nama / usaha',l.name)+field('problem','Kebutuhan atau masalah',l.problem)+select('stage','Tahap',stages,l.stage)+field('value','Nilai estimasi (Rp), isi 0 jika belum diketahui',l.value??0,'number')+field('next','Tindakan berikutnya',l.next)+field('date','Tanggal tindak lanjut',l.date,'date'),d=>{d.id=l.id||crypto.randomUUID();d.value=Number(d.value);if(l.id)state.leads[state.leads.findIndex(x=>x.id===l.id)]=d;else state.leads.push(d)})}
function entry(id){const old=state.entries.find(e=>e.id===id)||{};modal(old.id?'Edit catatan':'Catat transaksi',field('title','Uraian / proyek',old.title)+select('type','Jenis catatan',['Omzet','Kas masuk','Biaya'],old.type)+field('value','Nilai (Rp)',old.value,'number')+field('date','Tanggal',old.date||today(),'date'),d=>{d.value=Number(d.value);if(d.value<=0){toast('Nilai harus lebih dari nol.');return false}d.id=old.id||crypto.randomUUID();if(old.id)state.entries[state.entries.findIndex(e=>e.id===old.id)]=d;else state.entries.push(d)})}
function decision(){modal('Catat keputusan',field('title','Keputusan / ide')+select('status','Status',['USULAN','EKSPERIMEN','FINAL'],'USULAN')+field('source','Sumber persetujuan atau alasan'),d=>state.decisions.push({...d,id:crypto.randomUUID()}))}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#app').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit)lead(b.dataset.edit);if(b.dataset.entry)entry(b.dataset.entry);if(b.dataset.doc!==undefined){docIndex=Number(b.dataset.doc);render()}if(b.dataset.action==='lead')lead();if(b.dataset.action==='entry')entry();if(b.dataset.action==='decision')decision();if(b.dataset.action==='download-doc'){const d=window.HQ_DOCS[docIndex];download(d.path.split('/').pop(),d.content,'text/markdown')}});
$('#app').addEventListener('change',e=>{if(e.target.id==='filter'){filter=e.target.value;render()}if(e.target.id==='month'){month=e.target.value||today().slice(0,7);render()}if(e.target.id==='start'){state.start=e.target.value;save()}for(const k of ['task','road'])if(e.target.dataset[k]!==undefined){const index=Number(e.target.dataset[k]),array=k==='task'?'tasks':'road';state[array]=e.target.checked?[...new Set([...state[array],index])]:state[array].filter(i=>i!==index);save()}});
$('#app').addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
$('#close').onclick=$('#cancel').onclick=()=>$('#modal').close();
$('#export').onclick=()=>download(`somesea-data-${today()}.json`,JSON.stringify(state,null,2),'application/json');
$('#import').onclick=()=>$('#import-file').click();
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error();const incoming=JSON.parse(await file.text());if(!valid(incoming))throw Error();modal('Impor cadangan',`<p>Cadangan berisi ${incoming.leads.length} prospek, ${incoming.entries.length} transaksi, dan ${incoming.decisions.length} keputusan baru. Data saat ini akan diganti.</p><p>Ekspor data saat ini terlebih dahulu jika ingin menyimpannya.</p>`,()=>{state=incoming})}catch{toast('File tidak valid. Gunakan cadangan JSON dari Somesea HQ (maks. 2 MB).')}e.target.value=''};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
